SELECT store_id, name FROM stores WHERE city='Graz' OR name LIKE '%Graz%' OR name LIKE '%Lend%';
SELECT sku, path, brand, series, model, product_name, properties FROM products WHERE brand='Uvex' AND model='3MR-QL3' LIMIT 20;
SELECT sku, path, brand, series, model, product_name, properties FROM products WHERE brand='Uponor' AND model='35M-6XO' LIMIT 20;
SELECT sku, path, brand, series, model, product_name, properties FROM products WHERE brand='Stihl' AND model='DUW-0VN' LIMIT 20;
SELECT sku, path, brand, series, model, product_name, properties FROM products WHERE brand='Fischer' AND model='NT9-HP1' LIMIT 20;
SELECT sku, path, brand, series, model, product_name, properties FROM products WHERE brand='Milwaukee' AND model='5AB-LER' LIMIT 20;
SELECT sku, path, brand, series, model, product_name, properties FROM products WHERE brand='Hager' AND model='1RH-81U' LIMIT 20;

SELECT store_id, store_name, city, record_path FROM stores ORDER BY city, store_name LIMIT 50;
SELECT product_sku, record_path FROM product_variants WHERE brand='Uvex' AND series='Uvex Industrial' AND model='x-fit 3MR-QL3' AND product_name LIKE '%Safety Eyewear%' AND json_extract(properties,'$.lens_color') IN ('Gray','gray') AND json_extract(properties,'$.size') IN ('one size','One Size') AND json_extract(properties,'$.coating')='anti scratch' LIMIT 10;
SELECT product_sku, record_path FROM product_variants WHERE brand='Uponor' AND series='Press Fit Aqua' AND model='35M-6XO' AND product_name LIKE '%Pipe Fitting%' AND json_extract(properties,'$.fitting_type')='thread adapter' AND json_extract(properties,'$.diameter_mm')=25 AND json_extract(properties,'$.connection_type')='press' LIMIT 10;
SELECT product_sku, record_path FROM product_variants WHERE brand='Stihl' AND series='AK System HSA' AND model='DUW-0VN' AND product_name LIKE '%Chainsaw%' AND json_extract(properties,'$.power_source')='battery' AND json_extract(properties,'$.bar_length_cm')=20 LIMIT 10;
SELECT product_sku, record_path FROM product_variants WHERE brand='Fischer' AND series='Outdoor' AND model='SX NT9-HP1' AND product_name LIKE '%Nut Bolt and Washer%' AND json_extract(properties,'$.fastener_type')='bolt' AND json_extract(properties,'$.diameter_mm')=10 LIMIT 10;
SELECT product_sku, record_path FROM product_variants WHERE brand='Milwaukee' AND series='Professional M18' AND model='5AB-LER' AND product_name LIKE '%Corded Angle Grinder%' AND json_extract(properties,'$.disc_diameter_mm')=230 AND json_extract(properties,'$.power_w')=650 LIMIT 10;
SELECT product_sku, record_path FROM product_variants WHERE brand='Hager' AND series='Workshop' AND model='HAG 1RH-81U' AND product_name LIKE '%Extension Cable%' AND json_extract(properties,'$.color_family') IN ('Black','black') AND json_extract(properties,'$.length_m')=25 LIMIT 10;
